package kome.common.data;
import java.util.UUID;import net.minecraft.nbt.NBTTagCompound;
/** Versioned authority for the final Serfdom travel duty. */
public final class KOMESerfCourierAssignment {
 public static final int VERSION=1; public static final int MIN_COURIER_DISTANCE=256; public static final String RULE_SAME_FACTION_ADULT_NPC="same_faction_adult_npc"; public enum Kind { MESSAGE("message"),PARCEL("parcel");public final String key;Kind(String k){key=k;}static Kind of(String k){for(Kind v:values())if(v.key.equals(k))return v;return null;} } public static final int MESSAGE_WEIGHT=1,PARCEL_WEIGHT=1;
 public enum Stage { OUTBOUND("outbound"),DELIVERED("delivered"); public final String key;Stage(String k){key=k;}static Stage of(String k){for(Stage s:values())if(s.key.equals(k))return s;return null;} }
 public final String masterFactionKey,token;public final int dimension;public final double x,y,z;public final int minimumDistance;public Kind kind=Kind.MESSAGE;public String cargo="";public Stage stage;public KOMEProgressionNpcRef recipient;
 public KOMESerfCourierAssignment(String faction,String token,int dim,double x,double y,double z,int distance,Stage stage,KOMEProgressionNpcRef recipient){masterFactionKey=faction==null?"":faction;this.token=token==null?"":token;dimension=dim;this.x=x;this.y=y;this.z=z;minimumDistance=distance;this.stage=stage;this.recipient=recipient==null?KOMEProgressionNpcRef.EMPTY:recipient;}
 public static KOMESerfCourierAssignment create(KOMEProgressionNpcRef master){KOMESerfCourierAssignment a=new KOMESerfCourierAssignment(master.factionKey,UUID.randomUUID().toString(),master.dimension,master.x,master.y,master.z,MIN_COURIER_DISTANCE,Stage.OUTBOUND,KOMEProgressionNpcRef.EMPTY);a.kind=new java.util.Random().nextBoolean()?Kind.MESSAGE:Kind.PARCEL;if(a.kind==Kind.PARCEL)a.cargo="Iron Ingots x8|Leather x4";return a;}
 public boolean valid(){return masterFactionKey.length()>0&&token.length()>0&&stage!=null&&minimumDistance>0;}
 public boolean farEnough(int dim,double px,double pz){double dx=px-x,dz=pz-z;return dim==dimension&&dx*dx+dz*dz>=minimumDistance*(double)minimumDistance;}
 public NBTTagCompound writeToNBT(){NBTTagCompound t=new NBTTagCompound();t.setInteger("Version",VERSION);t.setString("Kind",kind.key);t.setString("Cargo",cargo);t.setString("Stage",stage.key);t.setString("MasterFactionKey",masterFactionKey);t.setString("RecipientRuleKey",RULE_SAME_FACTION_ADULT_NPC);t.setTag("RecipientNpc",recipient.writeToNBT());t.setInteger("MasterDimension",dimension);t.setDouble("MasterX",x);t.setDouble("MasterY",y);t.setDouble("MasterZ",z);t.setInteger("MinimumTravelDistance",minimumDistance);t.setString("PackageId",token);return t;}
 public static KOMESerfCourierAssignment readFromNBT(NBTTagCompound t){if(t==null||t.getInteger("Version")!=VERSION||!RULE_SAME_FACTION_ADULT_NPC.equals(t.getString("RecipientRuleKey")))return null;KOMESerfCourierAssignment a=new KOMESerfCourierAssignment(t.getString("MasterFactionKey"),t.getString("PackageId"),t.getInteger("MasterDimension"),t.getDouble("MasterX"),t.getDouble("MasterY"),t.getDouble("MasterZ"),t.getInteger("MinimumTravelDistance"),Stage.of(t.getString("Stage")),KOMEProgressionNpcRef.readFromNBT(t.getCompoundTag("RecipientNpc")));a.kind=Kind.of(t.getString("Kind"));a.cargo=t.getString("Cargo");return a.valid()&&a.kind!=null?a:null;}
}
